package br.com.archlab.simulation.core.v3;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ResultProjectionV3Test {
    static IdentifierV3 id(String x){return new IdentifierV3(x);}
    @Test void projectsReferenceMetricsAndReconstructsEveryPublicEntity(){var engine=new SimulationEngineV3(AsynchronousExecutionV3Test.reference(ExecutionPlanV3.AwaitPublish.NONE,Map.of()));var checkpoint=engine.run();var result=ResultProjectorV3.project(checkpoint);assertEquals(120L,result.metrics().principalResponseDurationMs());assertEquals(210L,result.metrics().globalCompletionDurationMs());assertEquals(90L,result.metrics().backgroundDurationAfterResponseMs());
        var api=result.metrics().components().stream().filter(x->x.componentId().equals(id("api"))).findFirst().orElseThrow();assertEquals(60,api.totalProcessingWorkMs());assertEquals(60,api.totalWaitingWorkMs());assertEquals(20,api.totalCommunicationWorkMs());
        var telemetry=result.metrics().components().stream().filter(x->x.componentId().equals(id("telemetry"))).findFirst().orElseThrow();assertEquals(90,telemetry.totalProcessingWorkMs());var pool=result.metrics().resources().stream().filter(x->x.resourceId().equals(id("telemetry-pool"))).findFirst().orElseThrow();assertEquals(90,pool.totalBusyCapacityMs());assertEquals(1,pool.maxObservedInUse());assertEquals(result.finalState(),PublicReplayV3.replay(result.initialState(),result.deltas(),checkpoint.current().trace(),210));
        var facts=new HashSet<IdentifierV3>();checkpoint.current().trace().forEach(x->facts.add(x.recordId()));var activities=new HashSet<IdentifierV3>();result.timeline().forEach(x->activities.add(x.activityId()));for(var activity:result.timeline()){assertTrue(facts.contains(activity.sourceTraceRecordId()));if(activity.endTraceRecordId()!=null)assertTrue(facts.contains(activity.endTraceRecordId()));if(activity.parentActivityId()!=null)assertTrue(activities.contains(activity.parentActivityId()));}}
    @Test void horizonUsesObservedPartialProcessingAndKeepsOpenTimelineIntervals(){var original=AsynchronousExecutionV3Test.reference(ExecutionPlanV3.AwaitPublish.NONE,Map.of());var request=new SimulationRequestV3(original.architecture(),original.scenario(),new SimulationRequestV3.Options(7,SimulationRequestV3.CompletionMode.UNTIL_HORIZON,150L));var engine=new SimulationEngineV3(request);var result=ResultProjectorV3.project(engine.run());assertEquals(120L,result.metrics().principalResponseDurationMs());assertNull(result.metrics().globalCompletionDurationMs());assertEquals(30L,result.metrics().backgroundDurationAfterResponseMs());assertEquals(30,result.metrics().components().stream().filter(x->x.componentId().equals(id("telemetry"))).findFirst().orElseThrow().totalProcessingWorkMs());assertTrue(result.timeline().stream().anyMatch(x->id("telemetry").equals(x.componentId()) && x.endedAtMs()==null));assertEquals(150,result.finalState().virtualTimeMs());}
    @Test void groupMetricsDistinguishJoinReleaseFromAllBranchesTerminal(){var engine=new SimulationEngineV3(AsynchronousExecutionV3Test.groups(ExecutionPlanV3.JoinPolicy.QUORUM,ExecutionPlanV3.RemainingPolicy.CONTINUE,2,null,10,20,70));var result=ResultProjectorV3.project(engine.run());var group=result.metrics().parallelGroups().getFirst();assertEquals(0,group.startedAtMs());assertEquals(20L,group.joinSatisfiedAtMs());assertEquals(70L,group.allBranchesTerminalAtMs());assertEquals(20L,result.metrics().principalResponseDurationMs());assertEquals(70L,result.metrics().globalCompletionDurationMs());}
    @Test void publicReplayRejectsWrongBeforeMissingSourceAndReorderedDeltas(){var result=ResultProjectorV3.project(new SimulationEngineV3(SynchronousExecutionV3Test.fixture(null,null,false,true)).run());var deltas=new ArrayList<>(result.deltas());var original=deltas.getFirst();var invalid=new StateDeltaV3(original.deltaId(),original.sequence(),original.timestampMs(),id("missing-trace"),original.entityKind(),original.entityId(),original.operation(),original.expectedVersion(),original.nextVersion(),original.before(),original.after());deltas.set(0,invalid);assertThrows(IllegalArgumentException.class,()->PublicReplayV3.replay(result.initialState(),deltas,result.checkpoint().current().trace(),result.finalState().virtualTimeMs()));
        var reversed=new ArrayList<>(result.deltas());Collections.reverse(reversed);assertThrows(IllegalArgumentException.class,()->PublicReplayV3.replay(result.initialState(),reversed,result.checkpoint().current().trace(),result.finalState().virtualTimeMs()));var repeated=new ArrayList<>(result.deltas());repeated.add(result.deltas().getLast());assertThrows(IllegalArgumentException.class,()->PublicReplayV3.replay(result.initialState(),repeated,result.checkpoint().current().trace(),result.finalState().virtualTimeMs()));}
    @Test void checkpointCannotBeResumedWithAnotherSeedOrArchitecture(){var original=SynchronousExecutionV3Test.fixture(null,null,false,true);var engine=new SimulationEngineV3(original);for(int i=0;i<8;i++)engine.step();var checkpoint=engine.checkpoint();var changed=new SimulationRequestV3(original.architecture(),original.scenario(),new SimulationRequestV3.Options(8,SimulationRequestV3.CompletionMode.DRAIN_ALL,null));assertThrows(IllegalArgumentException.class,()->SimulationEngineV3.resume(new SimulationEngineV3.Checkpoint(changed,checkpoint.initial(),checkpoint.current())));}
    @Test void inputFingerprintIgnoresPropertyMapInsertionOrderAndPreservesExactValues(){var a=new LinkedHashMap<String,Object>();a.put("alpha",1L);a.put("beta",true);var b=new LinkedHashMap<String,Object>();b.put("beta",true);b.put("alpha",1L);assertEquals(InputFingerprintV3.hash(a),InputFingerprintV3.hash(b));assertNotEquals(InputFingerprintV3.hash(a),InputFingerprintV3.hash(Map.of("alpha",2L,"beta",true)));}
}
